void SendWebUIMessage(gin::Arguments* args) {
  if (!args || !args->GetLength()) {
    return;
  }

  std::string message;
  if (!args->GetNext(&message)) {
    return;
  }

  if (message.empty()) {
    return;
  }

  scoped_refptr<base::Value> content;
  if (args->HasNext()) {
    v8::Local<v8::Value> content_value;
    if (args->GetNext(&content_value)) {
      content = base::Value::FromValue(content_value);
    }
  }

  if (ShouldRespondToRequest()) {
    if (MessageRequiresUserGesture(message) && !UserGestureDetected()) {
      LOG(ERROR) << "User gesture required for message: " << message;
      return;
    }

    RenderFrame::Send(message, content.get());
  }
}

